package com.company.skillplatform.user.application;
import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import com.company.skillplatform.user.domain.IdentityProviderType;import com.company.skillplatform.user.infrastructure.entity.IamUserEntity;import com.company.skillplatform.user.infrastructure.repository.IamUserRepository;import java.util.List;import org.junit.jupiter.api.Test;import org.springframework.data.domain.*;
class UserCandidateServiceTest{@Test void searchesActiveUsersAndCapsPageSize(){IamUserRepository users=mock(IamUserRepository.class);IamUserEntity user=new IamUserEntity(IdentityProviderType.MOCK,"u","user","h","User",null);when(users.findAll(org.mockito.ArgumentMatchers.<org.springframework.data.jpa.domain.Specification<IamUserEntity>>any(),any(Pageable.class))).thenAnswer(i->new PageImpl<>(List.of(user),i.getArgument(1),1));var result=new UserCandidateService(users).search("use",PageRequest.of(0,100));assertThat(result.getContent()).extracting(UserCandidateService.CandidateView::username).containsExactly("user");verify(users).findAll(org.mockito.ArgumentMatchers.<org.springframework.data.jpa.domain.Specification<IamUserEntity>>any(),org.mockito.ArgumentMatchers.<Pageable>argThat(p->p.getPageSize()==50));}}
